// Сверка собранного бандла с исходниками: что именно уехало на прод.
//
// ЗАЧЕМ ОТДЕЛЬНЫЙ СКРИПТ, А НЕ ПРОВЕРКА ГЛАЗАМИ.
//
//   1. КЛИЕНТ СОБИРАЕТСЯ НЕ В ОДИН ФАЙЛ. Правка в `api.ts` попадает не в
//      `index-*.js`, а в чанк `hud-*.js`. Поиск только по входному файлу даёт
//      честный и неверный ответ «правки в сборке нет» - так и вышло при первой
//      проверке, сразу False по всем маркерам.
//   2. РЕГУЛЯРКИ С КИРИЛЛИЦЕЙ В POWERSHELL ЛГУТ. `-match '\u043D\u0438\u0437'` и
//      `Select-String` с кириллическими литералами возвращали False на файле,
//      где слово есть, а консоль печатала вместо букв иероглифы. Проверено на
//      исходнике, где искомое слово точно есть. Поэтому здесь НЕТ НИ РЕГУЛЯРОК,
//      НИ РЕЖИМОВ КОДИРОВКИ: обычный поиск подстроки в файле, прочитанном utf8.
//
// ЗАЧЕМ ЭТО НУЖНО ПРИ ВЫКАТКЕ. `deploy.sh` сверяет образ и суммы sha256, но не
// говорит, какая именно правка внутри бандла. Этот скрипт отвечает на вопрос
// «а моя правка вообще доехала», не поднимая браузер и не заходя в игру.
//
// ЗАПУСК. `node client/tools/verify-bundle.mjs` из корня репозитория.
// Клиент должен быть собран (`npm run build` в client), иначе скрипт скажет об
// этом отдельно, а не промолчит.
import { readFileSync, existsSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const корень = 'D:/My Projects/Empire of Sefevids/client';
const ассеты = join(корень, 'web', 'game', 'assets');

/**
 * Что обязано быть в бандле, по чему это узнаётся и чего ждать.
 *
 * Ожидание задано ЯВНО, третьим элементом. Первая версия выводила его из слова
 * «убрано» в подписи — и промахнулась на подписи «убран», этого слова не
 * имеющей. Признак должен быть данными, а не догадкой по тексту подписи.
 *
 * Порядок неслучаен: сначала то, что ломает игру по-тихому (маршрут без
 * идентификатора, старое имя поля в логе), потом то, что просто должно быть.
 * Второе важно не меньше: отсутствие ожидаемой строки означает, что сборка
 * старше исходников, и приёмка на проде тогда бессмысленна.
 */
const ПРИЗНАКИ = [
  ['маршрут статуса голосования несёт characterId', 'vote/status?characterId=', true],
  ['сырой маршрут без characterId убран', 'vote/status`', false],
  ['лог называет поле низДоСдвига', 'низДоСдвига=', true],
  ['старое имя поля низ= убрано', 'низ=', false],
  ['фильтр дорожек на месте', 'выкинуто дорожек', true],
  ['фильтр называет недостающие кости', 'костей нет', true],
];

if (!existsSync(ассеты)) {
  console.log('СБОРКИ НЕТ: ' + ассеты);
  console.log('Соберите клиент: npm run build в client, потом запустите снова.');
  process.exit(1);
}

const чанки = readdirSync(ассеты).filter((ф) => ф.endsWith('.js'));
if (!чанки.length) {
  console.log('В ' + ассеты + ' нет ни одного .js: сборка пустая.');
  process.exit(1);
}

// Ищем по ВСЕМ чанкам сразу и печатаем, в каком нашлось. Один файл уводит в
// ложное «нет», и это уже стоило получаса.
const где = new Map();
for (const чанок of чанки) {
  const текст = readFileSync(join(ассеты, чанок), 'utf8');
  for (const [подпись, игла] of ПРИЗНАКИ) {
    const сколько = текст.split(игла).length - 1;
    if (сколько) {
      if (!где.has(подпись)) где.set(подпись, []);
      где.get(подпись).push(`${чанок}×${сколько}`);
    }
  }
}

let провалов = 0;
for (const [подпись, игла, ожидается] of ПРИЗНАКИ) {
  const найдено = где.get(подпись);
  if (ожидается && !найдено) {
    провалов++;
    console.log(`НЕТ    ${подпись} — искомого «${игла}» нет ни в одном чанке`);
  } else if (!ожидается && найдено) {
    провалов++;
    console.log(`ХУЖЕ   ${подпись} — нашлось там, где не должно: ${найдено.join(', ')}`);
  } else if (ожидается) {
    console.log(`ок     ${подпись} — ${найдено.join(', ')}`);
  } else {
    console.log(`ок     ${подпись}`);
  }
}

console.log(`\nчанков просмотрено: ${чанки.length}`);
console.log(
  провалов
    ? `ПРОВАЛОВ: ${провалов}. Сборка не соответствует исходникам.`
    : 'Сборка соответствует исходникам.',
);
process.exit(провалов ? 1 : 0);